{"implementation":"import math
def solve(case):
    matrix = case.get('matrix')
    if not matrix or not isinstance(matrix, list) or len(matrix) == 0:
        raise ValueError("Invalid matrix: empty or missing")
    if not all(isinstance(row, list) for row in matrix):
        raise ValueError("Invalid matrix: rows must be lists")
    n_rows = len(matrix)
    n_cols = len(matrix[0])
    if n_cols == 0:
        raise ValueError("Invalid matrix: zero columns")
    if any(len(row) != n_cols for row in matrix):
        raise ValueError("Invalid matrix: non-rectangular")
    idf = []
    for j in range(n_cols):
        df = sum(1 for row in matrix if row[j] != 0)
        idf_val = math.log(1.0 + n_rows / (1.0 + df))
        idf.append(idf_val)
    weighted_matrix = []
    row_degree = []
    for row in matrix:
        weighted_row = [float(entry) * idf[j] for j, entry in enumerate(row)]
        weighted_matrix.append(weighted_row)
        row_degree.append(sum(weighted_row))
    idf_rounded = [round(x, 6) for x in idf]
    weighted_matrix_rounded = [[round(x, 6) for x in row] for row in weighted_matrix]
    row_degree_rounded = [round(x, 6) for x in row_degree]
    return {
        'idf': idf_rounded,
        'row_degree': row_degree_rounded,
        'weighted_matrix': weighted_matrix_rounded
    }"}
